   263    static bool get_tuple_iterator (const GlyphVarData *var_data,
   264                                    unsigned int length,
   265                                    unsigned int axis_count,
   266                                    hb_vector_t<unsigned int> &shared_indices /* OUT */,
   267                                    tuple_iterator_t *iterator /* OUT */)
   268    {
   269      iterator->init (var_data, length, axis_count);
   270      if (!iterator->get_shared_indices (shared_indices))
   271        return false;
   272      return iterator->is_valid ();
   273    }
