   277    static bool unpack_points (const HBUINT8 *&p /* IN/OUT */,
   278                               hb_vector_t<unsigned int> &points /* OUT */,
   279                               const hb_bytes_t &bytes)
   280    {
   281      enum packed_point_flag_t
   282      {
   283        POINTS_ARE_WORDS     = 0x80,
   284        POINT_RUN_COUNT_MASK = 0x7F
   285      };
   286
   287      if (unlikely (!bytes.check_range (p))) return false;
   288
   289      uint16_t count = *p++;
   290      if (count & POINTS_ARE_WORDS)
   291      {
   292        if (unlikely (!bytes.check_range (p))) return false;
   293        count = ((count & POINT_RUN_COUNT_MASK) << 8) | *p++;
   294      }
   295      points.resize (count);
   296
   297      unsigned int n = 0;
   298      uint16_t i = 0;
   299      while (i < count)
   300      {
   301        if (unlikely (!bytes.check_range (p))) return false;
   302        uint16_t j;
   303        uint8_t control = *p++;
   304        uint16_t run_count = (control & POINT_RUN_COUNT_MASK) + 1;
   305        if (control & POINTS_ARE_WORDS)
   306        {
   307          for (j = 0; j < run_count && i < count; j++, i++)
   308          {
   309            if (unlikely (!bytes.check_range ((const HBUINT16 *) p)))
   310              return false;
   311            n += *(const HBUINT16 *)p;
   312            points[i] = n;
   313            p += HBUINT16::static_size;
   314          }
   315        }
   316        else
   317        {
   318          for (j = 0; j < run_count && i < count; j++, i++)
   319          {
   320            if (unlikely (!bytes.check_range (p))) return false;
   321            n += *p++;
   322            points[i] = n;
   323          }
   324        }
   325        if (j < run_count) return false;
   326      }
   327      return true;
   328    }
