   375    protected:
   376    TupleVarCount         tupleVarCount;
   377    OffsetTo<HBUINT8>     data;
   378    /* TupleVarHeader tupleVarHeaders[] */
   379    public:
   380    DEFINE_SIZE_MIN (4);
   381  };
